import java.sql.*;

public class TestDb {
    public static void main(String[] args) throws SQLException {
        // Establishing connection with database
        String url = "jdbc:mysql://localhost:3306/testdb";
        String username = "root";
        String password = "password123";

        // Creating a new connection to the database
        Connection con = DriverManager.getConnection(url, username, password);

        // Preparing a statement for executing an SQL query
        String sql = "SELECT * FROM student WHERE age > ?";
        PreparedStatement ps = con.prepareStatement(sql);

        // Binding the value to the question mark
        int age = 20;
        ps.setInt(1, age);

        // Executing the SQL query
        ResultSet rs = ps.executeQuery();

        // Processing the result set
        while (rs.next()) {
            System.out.println("ID: " + rs.getInt("id"));
            System.out.println("Name: " + rs.getString("name"));
            System.out.println("Age: " + rs.getInt("age"));
            System.out.println("Course: " + rs.getString("course"));
        }

        // Closing the resources
        con.close();
    }
}
```

This code snippet is set up to connect to a MySQL database, execute a SQL query that selects records from a `student` table where the age of the student is greater than 20, and print out the ID, name, age, and course for each matching record.

